    parameters: {
      query?: never;
      header?: never;
      path: {
        /** @description Organization ID */
        id: string;
      };
      cookie?: never;
    };
    requestBody?: never;
    responses: {
      /** @description Organization retrieved successfully */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': {
            /** @example org_1234567890 */
            id?: string;
            /** @example Tech Innovators */
            name?: string;
            /** @example https://example.com/logo.png */
            logo?: string;
            /** @example Building the future of technology */
            tagline?: string;
            /** @example We are a community of developers... */
            about?: string;
            links?: {
              /** @example https://techinnovators.com */
              website?: string;
              /** @example https://twitter.com/techinnovators */
              x?: string;
              /** @example https://github.com/techinnovators */
              github?: string;
              /** @example https://linkedin.com/company/techinnovators */
              others?: string;
            };
            /**
             * @example [
             *       "user_123",
             *       "user_456"
             *     ]
             */
            members?: string[];
            /**
             * @example [
             *       "user_123"
             *     ]
             */
            admins?: string[];
            /** @example user_123 */
            owner?: string;
            /** @example [] */
            hackathons?: string[];
            /** @example [] */
            grants?: string[];
            /** @example true */
            isProfileComplete?: boolean;
            /**
             * @example [
             *       "invite_123"
             *     ]
             */
            pendingInvites?: string[];
            /** @example better_auth_org_123 */
            betterAuthOrgId?: string;
            /** @example false */
            isArchived?: boolean;
            /** @example null */
            archivedBy?: string;
            /** @example null */
            archivedAt?: string;
            /** @example 2024-01-15T10:30:00.000Z */
            createdAt?: string;
            /** @example 2024-01-15T10:30:00.000Z */
            updatedAt?: string;
            analytics?: {
              trends?: {
                members?: {
                  /** @example 25 */
                  current?: number;
                  /** @example 22 */
                  previous?: number;
                  /** @example 3 */
                  change?: number;
                  /** @example 13.64 */
                  changePercentage?: number;
                  /** @example true */
                  isPositive?: boolean;
                };
                hackathons?: {
                  /** @example 5 */
                  current?: number;
                  /** @example 4 */
                  previous?: number;
                  /** @example 1 */
                  change?: number;
                  /** @example 25 */
                  changePercentage?: number;
                  /** @example true */
                  isPositive?: boolean;
                };
                grants?: {
                  /** @example 0 */
                  current?: number;
                  /** @example 0 */
                  previous?: number;
                  /** @example 0 */
                  change?: number;
                  /** @example 0 */
                  changePercentage?: number;
                  /** @example true */
                  isPositive?: boolean;
                };
              };
              timeSeries?: {
                hackathons?: {
                  /** @example January */
                  month?: string;
                  /** @example 2024 */
                  year?: number;
                  /** @example 2 */
                  count?: number;
                  /** @example 2024-01-01T00:00:00.000Z */
                  timestamp?: string;
                }[];
              };
            };
          };
        };
      };
      /** @description Organization not found */
      404: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
    };
